<section class="theme-related-articles theme-section" data-theme-block="related_articles"><div class="theme-container"><h2>{{ $settings['heading'] }}</h2><div class="theme-article-grid" style="--article-columns: {{ min(4, max(1, (int) $settings['columns'])) }}">@forelse($articles as $article)<x-theme::article-card :article="$article" :show-excerpt="(bool) $settings['show_excerpt']" :show-category="(bool) $settings['show_category']" :show-date="(bool) $settings['show_date']" :show-image="(bool) $settings['show_image']" :image-ratio="$settings['image_ratio']" />@empty<x-theme::empty-state title="مقاله مرتبطی برای نمایش وجود ندارد" />@endforelse</div></div></section>
